URL: https://www.museabrugge.be/en/visit/locations/groeningemuseum
Content-Type: text/html
Method: native

---

---
meta_omitted: "msapplication-TileColor, theme-color, viewport; read the URL with :raw for their values"
---

.mobileHeader {
text-align: left;
}
.mobileHeader .enviso-ticket-widget-offers-header {
margin: 0;
}
enviso-basket-button-wrapper .enviso-basket-button-wrapper {

}
:host {
--enviso-primary-color: #000000;
--enviso-secondary-color: #000000;
border-radius: 0;
}
:host([primary]) {
background-color: #000000;
border-radius: 0;
}
.enviso-offer-meta-element {
display: none !important;
}
.enviso-filter-text {
font-size: 18px;
}
.enviso-timeslot-description {
width: 100%;
}
/* The widget lays the timeslots out in a single column below its own
breakpoint, which makes a long list for museums with many slots.
From tablet up, put two side by side (as on BRUSK). */
@media (min-width: 768px) {
.enviso-timeslots-container {
grid-template-columns: 1fr 1fr;
}
}
.enviso-filter-button:first-of-type {
display: none;
}
.enviso-ticket-widget-offers-header,
.enviso-ticket-widget-offer-name {
font-family: 'Kommon Grotesk', 'sans-serif';
font-weight: 400;
font-size: 1.5rem;
line-height: 2.25rem;
margin-top: 1rem;
color: #000000;
}
@media (min-width: 768px) {
.enviso-ticket-widget-offers-header,
.enviso-ticket-widget-offer-name {
font-size: 2rem;
line-height: 2.5rem;
}
}
.enviso-steps-header-wrapper,
.enviso-steps-header-progress {
max-width: none;
}

.enviso-dates .enviso-day.enviso-disabled {
color: #BBB;
}
.enviso-dates .enviso-day.enviso-selected,
.enviso-dates .enviso-day.enviso-range-start,
.enviso-dates .enviso-day.enviso-range-end {
border: 1px solid #000;
background-color: #ff1428 !important;
color: #fff;
outline: none;
}
.enviso-day.enviso-in-range:not(.enviso-range-start):not(.enviso-range-end) {
background-color: #000000 !important;
color: #fff;
}
.enviso-ticket-wrapper {
margin-top: 60px;
}
.enviso-title {
font-size: 24px;
font-weight: 700;
margin-bottom: 12px;
color: black;
}
.enviso-basket-item-quantity-label {
position: relative;
top: auto;
right: auto;
padding: 0 .5em;
background: #707070;
color: #fff;
font-size: 16px;
text-align: center;
flex: 0;
font-weight: 700;
}
.enviso-basket-item-quantity-label::before {
content: 'Number: ';
}
.enviso-basket-offer-image {
margin-right: 15px;
}
.enviso-btn.primary {
min-height: 42px;
display: inline-flex;
justify-content: center;
align-items: center;
color: #fff;
font-size: 16px;
line-height: 21px;
font-weight: 700;
background-color: #ff1428;
position: relative;
overflow: hidden;
transition-property: color, background-color, border-color, outline-color, text-decoration-color, fill, stroke;
transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
transition-duration: 350;
}
.enviso-btn.primary:hover {
color: #fff;
background-color: #ff1428;
}
.enviso-customer-info-item a {
font-weight: 700;
color: black;
}
.btnNext,
.enviso-btnNext {
height: 100%;
color: black;
}
.btnNext,
.enviso-btnNext,
.btnPreviousStep {
margin-top: 0;
margin-bottom: 0;
color: black;
border-radius: 4px;
}
.enviso-discount-apply-btn {
height: 100%;
}
.enviso-discount-open:not(.enviso-hidden) {
display: flex;
}
.enviso-txt-wrapper,
.enviso-select-box-wrapper {
margin-bottom: 1rem;
}
.enviso-txt-error-message {
margin-bottom: 1rem;
}
.enviso-txt-error-message p {
margin-top: -0.8rem;
}
.enviso-txt-label {
margin-bottom: 0;
color: black;
}
.enviso-txt-info {
color: black;
margin-top: .5rem;
}
.enviso-offer-name {
font-weight: 400;
font-size: 21px;
line-height: 28px;
}
.enviso-basket-button-items-amount {
background: #FF1428;
color: #fff;
font-weight: 700;
}
.enviso-txt-value,
.enviso-select-value {
border-radius: 0;
font-size: 1rem;
max-width: 38em;
}
.enviso-txt-value {
padding: 14px 10px 10px;
}
.enviso-select-value {
padding: .75rem 2rem .75rem 1rem;
}
.enviso-checkbox-box label {
display: inline-block;
}
.enviso-checkbox-box label:before {
border-width: 1px;
border-color: black !important;
border-radius: 0;
}
.enviso-checkbox-box input:checked + label:after {
content: "";
height: 8px;
width: 10.4px;
background: url("data:image/svg+xml,%3Csvg width='11' height='9' viewBox='0 0 11 9' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath fill-rule='evenodd' clip-rule='evenodd' d='M8.80105 0.949753L10.4022 2.54978L4.00108 8.94975L0 4.94975L1.6011 3.34979L4.00108 5.74977L8.80105 0.949753Z' fill='black'/%3E%3C/svg%3E ") no-repeat center center;
background-size: contain;
position: absolute;
left: 50%;
top: 50%;
transform: translate(-50%, -50%);
border:0;
}
.enviso-select-label {
color: black;
}
.enviso-txt-value:focus,
.enviso-select-value:focus {
outline: #000000 1px solid;
border: none;
box-shadow: none;
}
summary.enviso-offer-details {
display: none;
}
.enviso-header {
margin-bottom: 20px;
}
.enviso-header-info {
padding-right: 15px;
}
.enviso-basket-offer-description-amount {
font-size: 1.3125rem;
line-height: 1.75rem;
font-weight: 700;
color: #000000;
}
.enviso-basket-item-entry-description-name {
font-weight: 700;
}
.enviso-basket-item-description-extra {
margin-top: 8px;
font-size: 16px;
color: #000000;
}
@media (min-width: 768px) {
.enviso-basket-item-description-extra {
font-size: 18px;
}
}
.enviso-continue-shopping {
display: flex;
align-items: center;
}
.enviso-offer-meta-element {
color: black;
}
.enviso-offers>enviso-offer-card {
position: relative;
padding-bottom: 50px;
}
.enviso-offer-info {
height: 100%;
}
.enviso-offer-actions {
position: absolute;
width: 100%;
left: 0;
bottom: 0;
} :host {
border-left: 6px solid #ff1428;
}
.enviso-name {
font-weight: 700;
}
.enviso-description,
.enviso-price {
margin-top: 12px;
}
.enviso-price-full {
font-weight: 400;
}
.enviso-product-image {
display: none;
}
.enviso-view-full-desc-btn {
color: #ff1428;
}
.enviso-dialog-backdrop-fullpage {
width: 100dvw;
height: 100dvh;
}
.enviso-dialog-backdrop-fullpage > .enviso-dialog-box {
overflow: auto;
max-height: 100%;
}
